window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"fg-i1026":{src:"fig:idioms:1026",route:"#/figurative",cta:"More idioms",title:"Idiom · leaps and bounds",body:"with very fast, impressive progress",source:"“Her vocabulary is growing by leaps and bounds this year.”"},"fg-i1027":{src:"fig:idioms:1027",route:"#/figurative",cta:"More idioms",title:"Idiom · leave in the lurch",body:"to abandon someone right when they need help",source:"“My project partner moved schools and left me in the lurch.”"},"fg-i1028":{src:"fig:idioms:1028",route:"#/figurative",cta:"More idioms",title:"Idiom · leave well enough alone",body:"don't tamper with something that is already fine",source:"“Your essay is great — leave well enough alone and go to bed.”"},"fg-i1029":{src:"fig:idioms:1029",route:"#/figurative",cta:"More idioms",title:"Idiom · the lesser of two evils",body:"the less harmful of two bad choices",source:"“Missing recess was the lesser of two evils compared to redoing the whole project.”"},"fg-i1030":{src:"fig:idioms:1030",route:"#/figurative",cta:"More idioms",title:"Idiom · let bygones be bygones",body:"forgive past quarrels and move on",source:"“The sisters let bygones be bygones and shared the last cupcake.”"},"fg-i1031":{src:"fig:idioms:1031",route:"#/figurative",cta:"More idioms",title:"Idiom · let nature take its course",body:"to let events unfold without interfering",source:"“We stopped fussing over the classroom caterpillar and let nature take its course.”"},"fg-i1032":{src:"fig:idioms:1032",route:"#/figurative",cta:"More idioms",title:"Idiom · light a fire under",body:"to push a slow person into acting fast",source:"“The deadline lit a fire under both of us to finish the poster.”"},"fg-i1033":{src:"fig:idioms:1033",route:"#/figurative",cta:"More idioms",title:"Idiom · live and learn",body:"mistakes teach us as life goes on",source:"“I packed the wrong word list — oh well, live and learn.”"},"fg-i1034":{src:"fig:idioms:1034",route:"#/figurative",cta:"More idioms",title:"Idiom · live and let live",body:"accept others as they are and expect the same back",source:"“Our lunch table's rule is live and let live — no teasing anyone's snacks.”"},"fg-i1035":{src:"fig:idioms:1035",route:"#/figurative",cta:"More idioms",title:"Idiom · the long arm of the law",body:"the police's power to reach wrongdoers anywhere",source:"“In our board game, no robber escapes the long arm of the law.”"},"fg-i1036":{src:"fig:idioms:1036",route:"#/figurative",cta:"More idioms",title:"Idiom · long story short",body:"skipping the details and getting to the point",source:"“Long story short, the dog buried my spelling notebook.”"},"fg-i1037":{src:"fig:idioms:1037",route:"#/figurative",cta:"More idioms",title:"Idiom · look on the bright side",body:"to focus on the good parts of a bad situation",source:"“Look on the bright side: you'll know that word for next year's bee.”"},"fg-i1038":{src:"fig:idioms:1038",route:"#/figurative",cta:"More idioms",title:"Idiom · lower the bar",body:"to make the standard easier to meet",source:"“The coach refused to lower the bar just because the list was hard.”"},"fg-i1039":{src:"fig:idioms:1039",route:"#/figurative",cta:"More idioms",title:"Idiom · make a name for yourself",body:"to become known and respected for what you do",source:"“She made a name for herself as the fastest fact-checker in class.”"},"fg-i1040":{src:"fig:idioms:1040",route:"#/figurative",cta:"More idioms",title:"Idiom · make do",body:"to manage with whatever you have",source:"“We forgot the flashcards, so we made do with sticky notes.”"},"fg-i1041":{src:"fig:idioms:1041",route:"#/figurative",cta:"More idioms",title:"Idiom · make or break",body:"bringing either total success or total failure",source:"“The last word of the round can make or break a speller.”"},"fg-i1042":{src:"fig:idioms:1042",route:"#/figurative",cta:"More idioms",title:"Idiom · make short work of",body:"to finish something quickly and easily",source:"“My brother made short work of the leftover birthday cake.”"},"fg-i1043":{src:"fig:idioms:1043",route:"#/figurative",cta:"More idioms",title:"Idiom · a man of few words",body:"a person who speaks little but means what he says",source:"“Grandpa is a man of few words, but his 'well done' means everything.”"},"fg-i1044":{src:"fig:idioms:1044",route:"#/figurative",cta:"More idioms",title:"Idiom · many moons ago",body:"a very long time ago",source:"“Many moons ago, Dad won his own school spelling bee.”"},"fg-i1045":{src:"fig:idioms:1045",route:"#/figurative",cta:"More idioms",title:"Idiom · mark my words",body:"remember what I say — it will prove true",source:"“Mark my words, that quiet new student will reach the finals.”"},"fg-i1046":{src:"fig:idioms:1046",route:"#/figurative",cta:"More idioms",title:"Idiom · a matter of course",body:"something expected that happens automatically",source:"“Checking her backpack the night before school is a matter of course now.”"},"fg-i1047":{src:"fig:idioms:1047",route:"#/figurative",cta:"More idioms",title:"Idiom · meet halfway",body:"to compromise, with each side giving up part",source:"“Mom met me halfway: twenty words tonight, twenty tomorrow.”"},"fg-i1048":{src:"fig:idioms:1048",route:"#/figurative",cta:"More idioms",title:"Idiom · the missing link",body:"the one piece needed to complete a chain or explanation",source:"“The dictionary's etymology was the missing link for spelling that word.”"},"fg-i1049":{src:"fig:idioms:1049",route:"#/figurative",cta:"More idioms",title:"Idiom · a moment in the sun",body:"a brief time of fame or glory",source:"“Winning the class bee gave him his moment in the sun.”"},"fg-i1050":{src:"fig:idioms:1050",route:"#/figurative",cta:"More idioms",title:"Idiom · the more the merrier",body:"the bigger the group, the more fun",source:"“Bring your cousins to game night — the more the merrier!”"},"fg-i1051":{src:"fig:idioms:1051",route:"#/figurative",cta:"More idioms",title:"Idiom · the mother of all battles",body:"the biggest, most extreme example of its kind",source:"“Cleaning the garage turned into the mother of all chores.”"},"fg-i1052":{src:"fig:idioms:1052",route:"#/figurative",cta:"More idioms",title:"Idiom · move heaven and earth",body:"to try everything imaginable to make something happen",source:"“Dad moved heaven and earth to get to my recital on time.”"},"fg-i1053":{src:"fig:idioms:1053",route:"#/figurative",cta:"More idioms",title:"Idiom · keep mum on the subject",body:"to refuse to say anything about a topic",source:"“She kept mum on the subject of what's inside the birthday box.”"},"fg-i1054":{src:"fig:idioms:1054",route:"#/figurative",cta:"More idioms",title:"Idiom · the name of the game",body:"the real point or most important part of an activity",source:"“In spelling bees, careful listening is the name of the game.”"},"fg-i1055":{src:"fig:idioms:1055",route:"#/figurative",cta:"More idioms",title:"Idiom · necessity is the mother of invention",body:"problems push people to invent solutions",source:"“No whiteboard? Necessity is the mother of invention — we used the window and dry-erase markers.”"},"fg-i1056":{src:"fig:idioms:1056",route:"#/figurative",cta:"More idioms",title:"Idiom · needless to say",body:"obviously; as everyone surely knows",source:"“Needless to say, the class hamster is the most popular classmate.”"},"fg-i1057":{src:"fig:idioms:1057",route:"#/figurative",cta:"More idioms",title:"Idiom · neither here nor there",body:"beside the point; not important to the matter",source:"“Whose turn it was is neither here nor there — the vase is broken.”"},"fg-i1058":{src:"fig:idioms:1058",route:"#/figurative",cta:"More idioms",title:"Idiom · never say die",body:"never give up, whatever happens",source:"“Down to her last lifeline word, she whispered 'never say die.'”"},"fg-i1059":{src:"fig:idioms:1059",route:"#/figurative",cta:"More idioms",title:"Idiom · new blood",body:"new members who bring fresh energy and ideas",source:"“The debate team needs new blood, so they invited third graders to try out.”"},"fg-i1060":{src:"fig:idioms:1060",route:"#/figurative",cta:"More idioms",title:"Idiom · no love lost",body:"open dislike between two people",source:"“There's no love lost between our school's chess team and their rivals.”"},"fg-i1061":{src:"fig:idioms:1061",route:"#/figurative",cta:"More idioms",title:"Idiom · no pain, no gain",body:"improvement demands hard, sometimes uncomfortable effort",source:"“Drilling fifty words a night is tough, but no pain, no gain.”"},"fg-i1062":{src:"fig:idioms:1062",route:"#/figurative",cta:"More idioms",title:"Idiom · no time like the present",body:"the best moment to act is right now",source:"“No time like the present — let's start the book report today.”"},"fg-i1063":{src:"fig:idioms:1063",route:"#/figurative",cta:"More idioms",title:"Idiom · no two ways about it",body:"absolutely certain; there is only one way to see it",source:"“No two ways about it, that was the best science fair project.”"},"fg-i1064":{src:"fig:idioms:1064",route:"#/figurative",cta:"More idioms",title:"Idiom · none the wiser",body:"still not knowing, even after it happened",source:"“We fixed the torn page, and the librarian was none the wiser.”"},"fg-i1065":{src:"fig:idioms:1065",route:"#/figurative",cta:"More idioms",title:"Idiom · not born yesterday",body:"too experienced to be tricked",source:"“Nice try hiding the broccoli, but I wasn't born yesterday.”"},"fg-i1066":{src:"fig:idioms:1066",route:"#/figurative",cta:"More idioms",title:"Idiom · not for all the tea in China",body:"not for any reward, however enormous",source:"“I wouldn't trade my lucky pencil, not for all the tea in China.”"},"fg-i1067":{src:"fig:idioms:1067",route:"#/figurative",cta:"More idioms",title:"Idiom · not hold a candle to",body:"not nearly as good as someone or something else",source:"“Store-bought cookies can't hold a candle to Grandma's.”"},"fg-i1068":{src:"fig:idioms:1068",route:"#/figurative",cta:"More idioms",title:"Idiom · not miss a beat",body:"to carry on smoothly without pausing or being thrown off",source:"“The fire alarm interrupted her word, and she spelled on without missing a beat.”"},"fg-i1069":{src:"fig:idioms:1069",route:"#/figurative",cta:"More idioms",title:"Idiom · not my strong suit",body:"not something I am good at",source:"“Fractions are not my strong suit, but spelling is.”"},"fg-i1070":{src:"fig:idioms:1070",route:"#/figurative",cta:"More idioms",title:"Idiom · go off the deep end",body:"to lose control and react wildly",source:"“Don't go off the deep end over one missed word.”"},"fg-i1071":{src:"fig:idioms:1071",route:"#/figurative",cta:"More idioms",title:"Idiom · old wives' tale",body:"a traditional belief that is not actually true",source:"“That carrots give you night vision is mostly an old wives' tale.”"},"fg-i1072":{src:"fig:idioms:1072",route:"#/figurative",cta:"More idioms",title:"Idiom · on a roll",body:"enjoying one success after another",source:"“Ten correct words in a row — she's on a roll!”"},"fg-i1073":{src:"fig:idioms:1073",route:"#/figurative",cta:"More idioms",title:"Idiom · on good terms",body:"friendly with each other",source:"“Even after the tournament, the two rival schools stayed on good terms.”"},"fg-i1074":{src:"fig:idioms:1074",route:"#/figurative",cta:"More idioms",title:"Idiom · on solid ground",body:"in a safe, well-supported position",source:"“Review the root words first so you're on solid ground for the quiz.”"},"fg-i1075":{src:"fig:idioms:1075",route:"#/figurative",cta:"More idioms",title:"Idiom · on the brink",body:"at the very edge of something about to happen",source:"“With one word left, she was on the brink of the championship.”"},"fg-i1076":{src:"fig:idioms:1076",route:"#/figurative",cta:"More idioms",title:"Idiom · on the cutting edge",body:"using the newest and most advanced methods",source:"“Our science teacher keeps the lab on the cutting edge with new robot kits.”"},"fg-i1077":{src:"fig:idioms:1077",route:"#/figurative",cta:"More idioms",title:"Idiom · on the horizon",body:"visible ahead; likely to happen soon",source:"“Report cards are on the horizon, so the whole house is studying.”"},"fg-i1078":{src:"fig:idioms:1078",route:"#/figurative",cta:"More idioms",title:"Idiom · on the mend",body:"recovering after an illness or setback",source:"“After a week of soup and rest, my brother is on the mend.”"},"fg-i1079":{src:"fig:idioms:1079",route:"#/figurative",cta:"More idioms",title:"Idiom · on the money",body:"exactly right or accurate",source:"“Her guess about the word's Latin origin was right on the money.”"},"fg-i1080":{src:"fig:idioms:1080",route:"#/figurative",cta:"More idioms",title:"Idiom · on the nose",body:"exactly right; precisely on target",source:"“The bake sale raised one hundred dollars on the nose.”"},"fg-i1081":{src:"fig:idioms:1081",route:"#/figurative",cta:"More idioms",title:"Idiom · on the rocks",body:"in deep trouble and close to failing",source:"“Our volcano project was on the rocks until Aunt Mia found more baking soda.”"},"fg-i1082":{src:"fig:idioms:1082",route:"#/figurative",cta:"More idioms",title:"Idiom · on your toes",body:"alert and ready to react",source:"“Surprise quizzes keep the whole class on their toes.”"},"fg-i1083":{src:"fig:idioms:1083",route:"#/figurative",cta:"More idioms",title:"Idiom · once and for all",body:"finally and for the last time",source:"“Let's settle once and for all who gets the top bunk.”"},"fg-i1084":{src:"fig:idioms:1084",route:"#/figurative",cta:"More idioms",title:"Idiom · one for the books",body:"so remarkable it deserves to be written down",source:"“Spelling the champion word blindfolded at practice — that was one for the books.”"},"fg-i1085":{src:"fig:idioms:1085",route:"#/figurative",cta:"More idioms",title:"Idiom · a little bird told me",body:"a playful way to say you heard a secret without naming who told you",source:"“A little bird told me you've been practicing your spelling words at recess.”"},"fg-i1086":{src:"fig:idioms:1086",route:"#/figurative",cta:"More idioms",title:"Idiom · albatross around your neck",body:"a burden or past mistake that keeps weighing you down",source:"“The unfinished science project hung like an albatross around her neck all vacation.”"},"fg-i1087":{src:"fig:idioms:1087",route:"#/figurative",cta:"More idioms",title:"Idiom · as the crow flies",body:"measured in a straight line, ignoring roads and turns",source:"“Our school is only a mile away as the crow flies, but the bus winds for three.”"},"fg-i1088":{src:"fig:idioms:1088",route:"#/figurative",cta:"More idioms",title:"Idiom · badger someone",body:"to pester someone with repeated questions or demands",source:"“My little brother badgered Mom for ice cream until she finally said yes.”"},"fg-i1089":{src:"fig:idioms:1089",route:"#/figurative",cta:"More idioms",title:"Idiom · bee in your bonnet",body:"an idea you cannot stop thinking or talking about",source:"“Ever since the science fair, Ria has had a bee in her bonnet about building a robot.”"},"fg-i1090":{src:"fig:idioms:1090",route:"#/figurative",cta:"More idioms",title:"Idiom · bird brain",body:"a silly or scatterbrained person",source:"“I felt like a bird brain when I forgot my own locker combination.”"},"fg-i1091":{src:"fig:idioms:1091",route:"#/figurative",cta:"More idioms",title:"Idiom · bull market",body:"a period when stock prices keep rising",source:"“Dad said his savings grew because of the bull market, so we celebrated with pizza.”"},"fg-i1092":{src:"fig:idioms:1092",route:"#/figurative",cta:"More idioms",title:"Idiom · bear market",body:"a period when stock prices keep falling",source:"“Grandpa explained that a bear market is why the news kept showing red arrows.”"},"fg-i1093":{src:"fig:idioms:1093",route:"#/figurative",cta:"More idioms",title:"Idiom · chicken feed",body:"a very small amount of money",source:"“Ten cents a chore is chicken feed, so I asked Dad for a real allowance.”"},"fg-i1094":{src:"fig:idioms:1094",route:"#/figurative",cta:"More idioms",title:"Idiom · cat's pajamas",body:"something or someone truly wonderful",source:"“Grandma says my spelling-bee trophy is the cat's pajamas.”"},"fg-i1095":{src:"fig:idioms:1095",route:"#/figurative",cta:"More idioms",title:"Idiom · chicken and egg problem",body:"a puzzle where you cannot tell which of two things caused the other",source:"“Needing experience to get experience is a chicken and egg problem, my sister groans.”"},"fg-i1096":{src:"fig:idioms:1096",route:"#/figurative",cta:"More idioms",title:"Idiom · clam up",body:"to suddenly refuse to speak",source:"“The new student clammed up when the teacher asked him to introduce himself.”"},"fg-i1097":{src:"fig:idioms:1097",route:"#/figurative",cta:"More idioms",title:"Idiom · cock and bull story",body:"a far-fetched story that is hard to believe",source:"“He gave Mom a cock and bull story about aliens eating his homework.”"},"fg-i1098":{src:"fig:idioms:1098",route:"#/figurative",cta:"More idioms",title:"Idiom · copycat",body:"someone who imitates what another person does",source:"“My little sister is such a copycat that she ordered exactly what I ordered.”"},"fg-i1099":{src:"fig:idioms:1099",route:"#/figurative",cta:"More idioms",title:"Idiom · dog's breakfast",body:"a complete mess",source:"“My first try at the poster was a dog's breakfast, so I started over.”"},"fg-i1100":{src:"fig:idioms:1100",route:"#/figurative",cta:"More idioms",title:"Idiom · donkey work",body:"the hard, boring part of a job",source:"“I did the donkey work of cutting out fifty paper stars for the class play.”"},"fg-i1101":{src:"fig:idioms:1101",route:"#/figurative",cta:"More idioms",title:"Idiom · duck out",body:"to leave quickly and quietly, often to avoid something",source:"“He tried to duck out of dish duty by hiding in his room.”"},"fg-i1102":{src:"fig:idioms:1102",route:"#/figurative",cta:"More idioms",title:"Idiom · eager beaver",body:"a person who is very enthusiastic and hardworking",source:"“The eager beaver in our class finished the worksheet before the teacher even sat down.”"},"fg-i1103":{src:"fig:idioms:1103",route:"#/figurative",cta:"More idioms",title:"Idiom · eat like a pig",body:"to eat noisily, messily, or far too much",source:"“Mom told me not to eat like a pig at Grandma's birthday dinner.”"},"fg-i1104":{src:"fig:idioms:1104",route:"#/figurative",cta:"More idioms",title:"Idiom · ferret out",body:"to hunt out hidden information",source:"“The librarian helped me ferret out the one book on medieval castles.”"},"fg-i1105":{src:"fig:idioms:1105",route:"#/figurative",cta:"More idioms",title:"Idiom · fish for information",body:"to try to get information by hinting rather than asking directly",source:"“My cousin fished for information about her surprise party all week.”"},"fg-i1106":{src:"fig:idioms:1106",route:"#/figurative",cta:"More idioms",title:"Idiom · fly the coop",body:"to escape or leave suddenly",source:"“The moment the last bell rang, we flew the coop for summer vacation.”"},"fg-i1107":{src:"fig:idioms:1107",route:"#/figurative",cta:"More idioms",title:"Idiom · go ape",body:"to become wildly excited or angry",source:"“The crowd went ape when our team won the district spelling bee.”"},"fg-i1108":{src:"fig:idioms:1108",route:"#/figurative",cta:"More idioms",title:"Idiom · go hog wild",body:"to behave with wild, unrestrained excitement",source:"“The class went hog wild when the teacher announced a pizza party.”"},"fg-i1109":{src:"fig:idioms:1109",route:"#/figurative",cta:"More idioms",title:"Idiom · guinea pig",body:"a person or thing used to test something new",source:"“I was the guinea pig for Dad's brand-new pancake recipe.”"},"fg-i1110":{src:"fig:idioms:1110",route:"#/figurative",cta:"More idioms",title:"Idiom · have a whale of a time",body:"to enjoy yourself enormously",source:"“We had a whale of a time at the school carnival.”"},"fg-i1111":{src:"fig:idioms:1111",route:"#/figurative",cta:"More idioms",title:"Idiom · have kittens",body:"to become extremely upset or anxious",source:"“Mom nearly had kittens when I came home covered in mud.”"},"fg-i1112":{src:"fig:idioms:1112",route:"#/figurative",cta:"More idioms",title:"Idiom · hen party",body:"a party for women only, often before a wedding",source:"“Aunt Priya's hen party was so loud we could hear the singing next door.”"},"fg-i1113":{src:"fig:idioms:1113",route:"#/figurative",cta:"More idioms",title:"Idiom · high horse",body:"an arrogant, superior attitude",source:"“Get off your high horse and admit you spelled it wrong too.”"},"fg-i1114":{src:"fig:idioms:1114",route:"#/figurative",cta:"More idioms",title:"Idiom · horse around",body:"to play in a rough, silly way",source:"“The coach told us to stop horsing around near the pool.”"},"fg-i1115":{src:"fig:idioms:1115",route:"#/figurative",cta:"More idioms",title:"Idiom · horse of a different color",body:"a completely different matter",source:"“Spelling 'cat' is easy, but 'chiaroscurist' is a horse of a different color.”"},"fg-i1116":{src:"fig:idioms:1116",route:"#/figurative",cta:"More idioms",title:"Idiom · in the lion's den",body:"in a dangerous place surrounded by hostile people",source:"“Walking into the rival school's gym for the final felt like entering the lion's den.”"},"fg-i1117":{src:"fig:idioms:1117",route:"#/figurative",cta:"More idioms",title:"Idiom · kangaroo court",body:"an unfair, fake court that has already decided you are guilty",source:"“The clubhouse trial felt like a kangaroo court because they never let me explain.”"},"fg-i1118":{src:"fig:idioms:1118",route:"#/figurative",cta:"More idioms",title:"Idiom · let the dog see the rabbit",body:"step aside and let someone get on with the job",source:"“'Move over and let the dog see the rabbit,' said Grandpa, taking the jammed printer.”"},"fg-i1119":{src:"fig:idioms:1119",route:"#/figurative",cta:"More idioms",title:"Idiom · like a deer in headlights",body:"frozen with surprise or fear",source:"“When the announcer called my name, I stood like a deer in headlights.”"},"fg-i1120":{src:"fig:idioms:1120",route:"#/figurative",cta:"More idioms",title:"Idiom · lone wolf",body:"someone who prefers to work or live alone",source:"“Sam is a lone wolf who studies his word lists by himself in the library.”"},"fg-i1121":{src:"fig:idioms:1121",route:"#/figurative",cta:"More idioms",title:"Idiom · make a beeline",body:"to go straight toward something quickly",source:"“After the final bell, we made a beeline for the ice-cream truck.”"},"fg-i1122":{src:"fig:idioms:1122",route:"#/figurative",cta:"More idioms",title:"Idiom · monkey see, monkey do",body:"people copy what they watch others do, without thinking",source:"“The toddler copies everything my brother does — monkey see, monkey do.”"},"fg-i1123":{src:"fig:idioms:1123",route:"#/figurative",cta:"More idioms",title:"Idiom · night owl",body:"a person who stays up late at night",source:"“Dad is a night owl, so he quizzes me on spelling words after dinner.”"},"fg-i1124":{src:"fig:idioms:1124",route:"#/figurative",cta:"More idioms",title:"Idiom · no spring chicken",body:"no longer young",source:"“Grandma jokes she's no spring chicken but still beats us at badminton.”"},"fg-i1125":{src:"fig:idioms:1125",route:"#/figurative",cta:"More idioms",title:"Idiom · one-trick pony",body:"someone or something with only one skill",source:"“He's no one-trick pony — he wins at spelling, chess, and soccer.”"},"fg-i1126":{src:"fig:idioms:1126",route:"#/figurative",cta:"More idioms",title:"Idiom · packed like sardines",body:"crowded very tightly together",source:"“We were packed like sardines on the field-trip bus.”"},"fg-i1127":{src:"fig:idioms:1127",route:"#/figurative",cta:"More idioms",title:"Idiom · paper tiger",body:"an enemy or threat that looks fierce but is actually weak",source:"“The quiz looked terrifying, but it was a paper tiger — I knew every word.”"},"fg-i1128":{src:"fig:idioms:1128",route:"#/figurative",cta:"More idioms",title:"Idiom · pig out",body:"to eat a huge amount greedily",source:"“We pigged out on popcorn during family movie night.”"},"fg-i1129":{src:"fig:idioms:1129",route:"#/figurative",cta:"More idioms",title:"Idiom · play possum",body:"to pretend to be asleep or dead",source:"“When Dad called bedtime, my brother played possum on the couch.”"},"fg-i1130":{src:"fig:idioms:1130",route:"#/figurative",cta:"More idioms",title:"Idiom · puppy love",body:"a young, short-lived crush",source:"“Mom says my sister's fifth-grade crush is just puppy love.”"},"fg-i1131":{src:"fig:idioms:1131",route:"#/figurative",cta:"More idioms",title:"Idiom · rat race",body:"an exhausting, competitive routine that never seems to end",source:"“Dad says summer break is his escape from the rat race.”"},"fg-i1132":{src:"fig:idioms:1132",route:"#/figurative",cta:"More idioms",title:"Idiom · road hog",body:"a driver who selfishly takes up too much road",source:"“Dad muttered 'road hog' when a truck blocked both lanes near school.”"},"fg-i1133":{src:"fig:idioms:1133",route:"#/figurative",cta:"More idioms",title:"Idiom · scaredy-cat",body:"a person who is easily frightened",source:"“Don't be a scaredy-cat — the haunted house is just paper decorations.”"},"fg-i1134":{src:"fig:idioms:1134",route:"#/figurative",cta:"More idioms",title:"Idiom · smell fishy",body:"to seem suspicious or dishonest",source:"“His excuse about the missing cookies smelled fishy to Mom.”"},"fg-i1135":{src:"fig:idioms:1135",route:"#/figurative",cta:"More idioms",title:"Idiom · social butterfly",body:"a person who flits happily from friend to friend",source:"“Nina is the class social butterfly, chatting with every table at lunch.”"},"fg-i1136":{src:"fig:idioms:1136",route:"#/figurative",cta:"More idioms",title:"Idiom · stool pigeon",body:"a person who secretly informs on others",source:"“Nobody wanted to be the stool pigeon who told the teacher about the paper airplanes.”"},"fg-i1137":{src:"fig:idioms:1137",route:"#/figurative",cta:"More idioms",title:"Idiom · swan around",body:"to wander about grandly doing nothing useful",source:"“Instead of packing her schoolbag, my sister swanned around in her new dress.”"},"fg-i1138":{src:"fig:idioms:1138",route:"#/figurative",cta:"More idioms",title:"Idiom · take under your wing",body:"to protect and guide someone less experienced",source:"“The fifth-grade champion took the newest speller under her wing.”"},"fg-i1139":{src:"fig:idioms:1139",route:"#/figurative",cta:"More idioms",title:"Idiom · talk turkey",body:"to talk honestly and get down to business",source:"“'Let's talk turkey,' said Coach: practice is every day or we forfeit.”"},"fg-i1140":{src:"fig:idioms:1140",route:"#/figurative",cta:"More idioms",title:"Idiom · the birds and the bees",body:"a gentle way to explain to children how babies are made",source:"“Dad turned red when my little brother asked about the birds and the bees.”"},"fg-i1141":{src:"fig:idioms:1141",route:"#/figurative",cta:"More idioms",title:"Idiom · top dog",body:"the person in charge or the winner",source:"“After winning regionals, Maya was top dog at spelling club.”"},"fg-i1142":{src:"fig:idioms:1142",route:"#/figurative",cta:"More idioms",title:"Idiom · ugly duckling",body:"someone awkward at first who grows into something wonderful",source:"“Our squeaky school band was an ugly duckling that won awards by spring.”"},"fg-i1143":{src:"fig:idioms:1143",route:"#/figurative",cta:"More idioms",title:"Idiom · watch someone like a hawk",body:"to watch very closely, missing nothing",source:"“The proctor watched us like a hawk during the spelling test.”"},"fg-i1144":{src:"fig:idioms:1144",route:"#/figurative",cta:"More idioms",title:"Idiom · weasel out of",body:"to escape a duty in a sneaky way",source:"“He tried to weasel out of raking leaves by claiming extra homework.”"},"fg-i1145":{src:"fig:idioms:1145",route:"#/figurative",cta:"More idioms",title:"Idiom · wolf down",body:"to eat something extremely fast",source:"“I wolfed down breakfast so I wouldn't miss the bus.”"},"fg-i1146":{src:"fig:idioms:1146",route:"#/figurative",cta:"More idioms",title:"Idiom · you can't teach an old dog new tricks",body:"people set in their ways struggle to learn new habits",source:"“Grandpa says you can't teach an old dog new tricks, yet he just learned to video-call.”"},"fg-i1147":{src:"fig:idioms:1147",route:"#/figurative",cta:"More idioms",title:"Idiom · doggy bag",body:"a bag for taking restaurant leftovers home",source:"“We brought Dad's birthday-dinner leftovers home in a doggy bag.”"},"fg-i1148":{src:"fig:idioms:1148",route:"#/figurative",cta:"More idioms",title:"Idiom · early bird special",body:"a restaurant discount for customers who eat early",source:"“Grandpa loves the diner's early bird special before our evening study sessions.”"},"fg-i1149":{src:"fig:idioms:1149",route:"#/figurative",cta:"More idioms",title:"Idiom · for donkey's years",body:"for a very long time",source:"“We haven't visited the science museum for donkey's years.”"},"fg-i1150":{src:"fig:idioms:1150",route:"#/figurative",cta:"More idioms",title:"Idiom · gone to the dogs",body:"fallen into a much worse condition",source:"“Grandpa grumbles that his favorite team has gone to the dogs.”"},"fg-i1151":{src:"fig:idioms:1151",route:"#/figurative",cta:"More idioms",title:"Idiom · like a bear with a sore head",body:"in a very grumpy, irritable mood",source:"“Dad is like a bear with a sore head before his morning coffee.”"},"fg-i1152":{src:"fig:idioms:1152",route:"#/figurative",cta:"More idioms",title:"Idiom · like a cat on a hot tin roof",body:"extremely nervous and unable to keep still",source:"“Waiting for the spelling-bee results, I was like a cat on a hot tin roof.”"},"fg-i1153":{src:"fig:idioms:1153",route:"#/figurative",cta:"More idioms",title:"Idiom · like a headless chicken",body:"rushing around in a panicked, disorganized way",source:"“I ran around like a headless chicken looking for my permission slip.”"},"fg-i1154":{src:"fig:idioms:1154",route:"#/figurative",cta:"More idioms",title:"Idiom · like shooting fish in a barrel",body:"extremely easy to do",source:"“For the returning champion, the first-round words were like shooting fish in a barrel.”"},"fg-i1155":{src:"fig:idioms:1155",route:"#/figurative",cta:"More idioms",title:"Idiom · mad as a wet hen",body:"furiously angry",source:"“Mom was mad as a wet hen when the dog tracked mud across the clean floor.”"},"fg-i1156":{src:"fig:idioms:1156",route:"#/figurative",cta:"More idioms",title:"Idiom · put the fox in charge of the henhouse",body:"to give a job to someone certain to abuse it",source:"“Letting my candy-loving brother guard the Halloween haul is putting the fox in charge of the henhouse.”"},"fg-i1157":{src:"fig:idioms:1157",route:"#/figurative",cta:"More idioms",title:"Idiom · black swan event",body:"a rare, unpredictable event with huge consequences",source:"“The surprise school closure was a black swan event that upended the bee calendar.”"},"fg-i1158":{src:"fig:idioms:1158",route:"#/figurative",cta:"More idioms",title:"Idiom · the canary in the coal mine",body:"an early warning of danger",source:"“My falling quiz scores were the canary in the coal mine for my skipped homework.”"},"fg-i1159":{src:"fig:idioms:1159",route:"#/figurative",cta:"More idioms",title:"Idiom · the goose that laid the golden egg",body:"a precious source of ongoing benefit, often destroyed by greed",source:"“The bake-sale brownie recipe is our club's goose that laid the golden egg.”"},"fg-i1160":{src:"fig:idioms:1160",route:"#/figurative",cta:"More idioms",title:"Idiom · there are plenty of fish in the sea",body:"there are many other chances or people left to choose from",source:"“When I lost the raffle, Mom smiled and said there are plenty of fish in the sea.”"},"fg-i1161":{src:"fig:idioms:1161",route:"#/figurative",cta:"More idioms",title:"Idiom · when the cat's away the mice will play",body:"people misbehave when the person in charge is gone",source:"“The substitute stepped out, and — when the cat's away, the mice will play — paper planes flew.”"},"fg-i1162":{src:"fig:idioms:1162",route:"#/figurative",cta:"More idioms",title:"Idiom · wild horses couldn't drag me away",body:"nothing could make me leave or miss it",source:"“Wild horses couldn't drag me away from the championship round.”"},"fg-i1163":{src:"fig:idioms:1163",route:"#/figurative",cta:"More idioms",title:"Idiom · you can lead a horse to water but you can't make it drink",body:"you can give someone an opportunity, but not force them to take it",source:"“I printed the study list, but you can lead a horse to water — my brother won't open it.”"},"fg-i1164":{src:"fig:idioms:1164",route:"#/figurative",cta:"More idioms",title:"Idiom · a lot on your plate",body:"many responsibilities to handle at once",source:"“Between rehearsals and word lists, Ana has a lot on her plate this month.”"},"fg-i1165":{src:"fig:idioms:1165",route:"#/figurative",cta:"More idioms",title:"Idiom · apple of discord",body:"a small thing that starts a big quarrel",source:"“The last cupcake became the apple of discord at the birthday party.”"},"fg-i1166":{src:"fig:idioms:1166",route:"#/figurative",cta:"More idioms",title:"Idiom · apples and oranges",body:"two things too different to compare fairly",source:"“Comparing soccer and spelling is apples and oranges — I love them both.”"},"fg-i1167":{src:"fig:idioms:1167",route:"#/figurative",cta:"More idioms",title:"Idiom · as easy as taking candy from a baby",body:"extremely easy to do",source:"“He bragged that the bonus round was as easy as taking candy from a baby.”"},"fg-i1168":{src:"fig:idioms:1168",route:"#/figurative",cta:"More idioms",title:"Idiom · big cheese",body:"the most important person in a group",source:"“The principal is the big cheese who decides when the bee starts.”"},"fg-i1169":{src:"fig:idioms:1169",route:"#/figurative",cta:"More idioms",title:"Idiom · bread of life",body:"something essential that feeds your spirit",source:"“At choir practice, Grandma calls her old hymn book the bread of life.”"},"fg-i1170":{src:"fig:idioms:1170",route:"#/figurative",cta:"More idioms",title:"Idiom · butter wouldn't melt in his mouth",body:"he looks sweetly innocent but probably is not",source:"“My brother sat there as if butter wouldn't melt in his mouth, hiding the empty cookie jar.”"},"fg-i1171":{src:"fig:idioms:1171",route:"#/figurative",cta:"More idioms",title:"Idiom · carrot and stick",body:"a mix of rewards and punishments used to persuade someone",source:"“Mom uses carrot and stick: dessert for finished homework, no tablet for whining.”"},"fg-i1172":{src:"fig:idioms:1172",route:"#/figurative",cta:"More idioms",title:"Idiom · cheesy grin",body:"a wide, silly, often fake smile",source:"“He flashed a cheesy grin for the class photo.”"},"fg-i1173":{src:"fig:idioms:1173",route:"#/figurative",cta:"More idioms",title:"Idiom · cherry on top",body:"a final small touch that makes something even better",source:"“Winning the bee was great; the photo in the paper was the cherry on top.”"},"fg-i1174":{src:"fig:idioms:1174",route:"#/figurative",cta:"More idioms",title:"Idiom · chew it over",body:"to think about something slowly and carefully",source:"“Dad said he'd chew it over before answering my request for a later bedtime.”"},"fg-i1175":{src:"fig:idioms:1175",route:"#/figurative",cta:"More idioms",title:"Idiom · cool beans",body:"great; wonderful",source:"“'Cool beans!' said Leo when practice moved to the big gym.”"},"fg-i1176":{src:"fig:idioms:1176",route:"#/figurative",cta:"More idioms",title:"Idiom · cream rises to the top",body:"the best people or ideas eventually stand out",source:"“Coach says to keep practicing — cream rises to the top.”"},"fg-i1177":{src:"fig:idioms:1177",route:"#/figurative",cta:"More idioms",title:"Idiom · cup of tea",body:"the kind of thing you like and enjoy",source:"“Scary movies aren't my cup of tea; I'd rather do a word puzzle.”"},"fg-i1178":{src:"fig:idioms:1178",route:"#/figurative",cta:"More idioms",title:"Idiom · duck soup",body:"something extremely easy",source:"“Fixing the wobbly desk was duck soup for the janitor.”"},"fg-i1179":{src:"fig:idioms:1179",route:"#/figurative",cta:"More idioms",title:"Idiom · eat your heart out",body:"a teasing way to say someone should feel envious",source:"“Eat your heart out, big sister — I finally beat your puzzle record.”"},"fg-i1180":{src:"fig:idioms:1180",route:"#/figurative",cta:"More idioms",title:"Idiom · eat your words",body:"to admit that what you said was wrong",source:"“You said I'd never spell 'onomatopoeia' — get ready to eat your words.”"},"fg-i1181":{src:"fig:idioms:1181",route:"#/figurative",cta:"More idioms",title:"Idiom · egg someone on",body:"to urge someone to do something, often something foolish",source:"“His friends egged him on to try the super-spicy salsa.”"},"fg-i1182":{src:"fig:idioms:1182",route:"#/figurative",cta:"More idioms",title:"Idiom · finger in every pie",body:"involved in many different activities at once",source:"“Our class rep has a finger in every pie — yearbook, recycling club, and the bee.”"},"fg-i1183":{src:"fig:idioms:1183",route:"#/figurative",cta:"More idioms",title:"Idiom · food coma",body:"the sleepy, sluggish feeling after eating a big meal",source:"“After Thanksgiving dinner, the whole family slid into a food coma.”"},"fg-i1184":{src:"fig:idioms:1184",route:"#/figurative",cta:"More idioms",title:"Idiom · forbidden fruit",body:"something wanted more because it is not allowed",source:"“The teacher's locked prize cabinet made those stickers forbidden fruit.”"},"fg-i1185":{src:"fig:idioms:1185",route:"#/figurative",cta:"More idioms",title:"Idiom · go bananas",body:"to become wildly excited or crazy",source:"“The gym went bananas when our mascot did a backflip.”"},"fg-i1186":{src:"fig:idioms:1186",route:"#/figurative",cta:"More idioms",title:"Idiom · go nuts",body:"to become crazy, furious, or wildly excited",source:"“Mom will go nuts if we track sand through the hallway.”"},"fg-i1187":{src:"fig:idioms:1187",route:"#/figurative",cta:"More idioms",title:"Idiom · half-baked",body:"not properly thought through",source:"“Building a treehouse in one afternoon was a half-baked idea.”"},"fg-i1188":{src:"fig:idioms:1188",route:"#/figurative",cta:"More idioms",title:"Idiom · hard cheese",body:"bad luck — often said without much sympathy",source:"“'Hard cheese,' said my cousin when rain cancelled the picnic.”"},"fg-i1189":{src:"fig:idioms:1189",route:"#/figurative",cta:"More idioms",title:"Idiom · hail mary",body:"a desperate last-chance attempt with little hope of success",source:"“Cramming the whole word list in the car was a hail mary before the bee.”"},"fg-i1190":{src:"fig:idioms:1190",route:"#/figurative",cta:"More idioms",title:"Idiom · hat trick",body:"three wins or successes in a row by one person",source:"“Winning her third spelling bee in a row completed the hat trick.”"},"fg-i1191":{src:"fig:idioms:1191",route:"#/figurative",cta:"More idioms",title:"Idiom · have the inside track",body:"to have a special advantage over competitors",source:"“Having read the book twice gave Maya the inside track in the trivia contest.”"},"fg-i1192":{src:"fig:idioms:1192",route:"#/figurative",cta:"More idioms",title:"Idiom · heavy hitter",body:"a powerful, important person in a field",source:"“Grandma is the heavy hitter of our family trivia team.”"},"fg-i1193":{src:"fig:idioms:1193",route:"#/figurative",cta:"More idioms",title:"Idiom · hit a home run",body:"to succeed impressively at something",source:"“Her volcano project hit a home run with the science fair judges.”"},"fg-i1194":{src:"fig:idioms:1194",route:"#/figurative",cta:"More idioms",title:"Idiom · hit below the belt",body:"to do something unfair or hurtful",source:"“Teasing your brother about his reading struggles is hitting below the belt.”"},"fg-i1195":{src:"fig:idioms:1195",route:"#/figurative",cta:"More idioms",title:"Idiom · hold all the cards",body:"to control a situation completely",source:"“In the negotiations over screen time, Dad holds all the cards.”"},"fg-i1196":{src:"fig:idioms:1196",route:"#/figurative",cta:"More idioms",title:"Idiom · home stretch",body:"the final part of a task or journey",source:"“One chapter left — we're in the home stretch of the book report.”"},"fg-i1197":{src:"fig:idioms:1197",route:"#/figurative",cta:"More idioms",title:"Idiom · in the cards",body:"likely to happen; seemingly destined",source:"“With storm clouds like these, a canceled picnic was always in the cards.”"},"fg-i1198":{src:"fig:idioms:1198",route:"#/figurative",cta:"More idioms",title:"Idiom · in your corner",body:"supporting and ready to help you",source:"“Whatever the report card says, Mom is in your corner.”"},"fg-i1199":{src:"fig:idioms:1199",route:"#/figurative",cta:"More idioms",title:"Idiom · keep the ball rolling",body:"to keep an activity going without a pause",source:"“Each cousin added a verse to keep the ball rolling on the birthday song.”"},"fg-i1200":{src:"fig:idioms:1200",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your eye on the ball",body:"to stay focused on what matters most",source:"“Ignore the giggles from the audience and keep your eye on the ball — one letter at a time.”"},"fg-i1201":{src:"fig:idioms:1201",route:"#/figurative",cta:"More idioms",title:"Idiom · kick off",body:"to begin an event or activity",source:"“The school fair kicks off with a pancake breakfast.”"},"fg-i1202":{src:"fig:idioms:1202",route:"#/figurative",cta:"More idioms",title:"Idiom · knock it out of the park",body:"to do something extremely well",source:"“Priya knocked it out of the park with her history presentation.”"},"fg-i1203":{src:"fig:idioms:1203",route:"#/figurative",cta:"More idioms",title:"Idiom · long shot",body:"an attempt with only a small chance of success",source:"“Winning regionals on her first try is a long shot, but she's studying anyway.”"},"fg-i1204":{src:"fig:idioms:1204",route:"#/figurative",cta:"More idioms",title:"Idiom · low blow",body:"an unfair or cruel act or remark",source:"“Bringing up her lost library book in the middle of the game was a low blow.”"},"fg-i1205":{src:"fig:idioms:1205",route:"#/figurative",cta:"More idioms",title:"Idiom · make the cut",body:"to qualify or be chosen for the next stage",source:"“Twenty spellers tried out for the team, and Aanya made the cut.”"},"fg-i1206":{src:"fig:idioms:1206",route:"#/figurative",cta:"More idioms",title:"Idiom · move the needle",body:"to make a noticeable difference",source:"“Ten extra minutes of reading each night really moved the needle on her fluency.”"},"fg-i1207":{src:"fig:idioms:1207",route:"#/figurative",cta:"More idioms",title:"Idiom · not playing with a full deck",body:"acting foolish or not thinking clearly",source:"“The dog buried Dad's phone again — that pup is not playing with a full deck.”"},"fg-i1208":{src:"fig:idioms:1208",route:"#/figurative",cta:"More idioms",title:"Idiom · off base",body:"mistaken or completely wrong",source:"“Your guess about the surprise party is way off base.”"},"fg-i1209":{src:"fig:idioms:1209",route:"#/figurative",cta:"More idioms",title:"Idiom · on target",body:"accurate; exactly right or on schedule",source:"“Her definition of 'onomatopoeia' was right on target.”"},"fg-i1210":{src:"fig:idioms:1210",route:"#/figurative",cta:"More idioms",title:"Idiom · on the ball",body:"alert, quick, and doing things well",source:"“You packed the permission slip a day early — nice to see you on the ball.”"},"fg-i1211":{src:"fig:idioms:1211",route:"#/figurative",cta:"More idioms",title:"Idiom · on the rebound",body:"recovering from a loss or disappointment",source:"“After losing the chess final, Leo was on the rebound by dinnertime, planning next year's strategy.”"},"fg-i1212":{src:"fig:idioms:1212",route:"#/figurative",cta:"More idioms",title:"Idiom · on the ropes",body:"close to defeat or failure",source:"“Our quiz team was on the ropes until the final science question.”"},"fg-i1213":{src:"fig:idioms:1213",route:"#/figurative",cta:"More idioms",title:"Idiom · out of left field",body:"completely unexpected and strange",source:"“Her question about penguins came out of left field in the middle of math.”"},"fg-i1214":{src:"fig:idioms:1214",route:"#/figurative",cta:"More idioms",title:"Idiom · out of your league",body:"too good or advanced for you",source:"“The eighth-grade word list felt out of her league — until she studied.”"},"fg-i1215":{src:"fig:idioms:1215",route:"#/figurative",cta:"More idioms",title:"Idiom · paddle upstream",body:"to struggle against strong opposition",source:"“Convincing the class to read during recess felt like paddling upstream.”"},"fg-i1216":{src:"fig:idioms:1216",route:"#/figurative",cta:"More idioms",title:"Idiom · photo finish",body:"a contest so close the winner is decided by a tiny margin",source:"“The bee ended in a photo finish, settled by one silent letter.”"},"fg-i1217":{src:"fig:idioms:1217",route:"#/figurative",cta:"More idioms",title:"Idiom · play ball",body:"to cooperate or agree to take part",source:"“The little kids will play ball with the cleanup plan as long as they get first turn at the games.”"},"fg-i1218":{src:"fig:idioms:1218",route:"#/figurative",cta:"More idioms",title:"Idiom · play hardball",body:"to act tough and compete without mercy",source:"“Mom played hardball: no dessert until every spelling word was perfect.”"},"fg-i1219":{src:"fig:idioms:1219",route:"#/figurative",cta:"More idioms",title:"Idiom · play the field",body:"to try many options before committing to one",source:"“Sam played the field — chess, choir, then robotics — before picking a club.”"},"fg-i1220":{src:"fig:idioms:1220",route:"#/figurative",cta:"More idioms",title:"Idiom · play your cards right",body:"to handle a situation cleverly for the best result",source:"“Play your cards right with early chores and we might make the museum by noon.”"},"fg-i1221":{src:"fig:idioms:1221",route:"#/figurative",cta:"More idioms",title:"Idiom · poker face",body:"a blank expression that hides your true feelings",source:"“Rhea kept a perfect poker face when she drew an easy final word.”"},"fg-i1222":{src:"fig:idioms:1222",route:"#/figurative",cta:"More idioms",title:"Idiom · punch above your weight",body:"to perform better than expected for your size or level",source:"“Our tiny school punches above its weight at the state bee every year.”"},"fg-i1223":{src:"fig:idioms:1223",route:"#/figurative",cta:"More idioms",title:"Idiom · raise the stakes",body:"to increase the risks or rewards involved",source:"“The teacher raised the stakes — the winning team skips Friday's homework.”"},"fg-i1224":{src:"fig:idioms:1224",route:"#/figurative",cta:"More idioms",title:"Idiom · right off the bat",body:"immediately; without any delay",source:"“Right off the bat, Grandpa guessed the answer to my riddle.”"},"fg-i1225":{src:"fig:idioms:1225",route:"#/figurative",cta:"More idioms",title:"Idiom · roll the dice",body:"to take a chance on an uncertain outcome",source:"“Skipping the review sheet the night before a test is really rolling the dice.”"},"fg-i1226":{src:"fig:idioms:1226",route:"#/figurative",cta:"More idioms",title:"Idiom · run interference",body:"to clear away problems so someone else can succeed",source:"“Dad ran interference with the chatty neighbors so Mia could finish studying.”"},"fg-i1227":{src:"fig:idioms:1227",route:"#/figurative",cta:"More idioms",title:"Idiom · score an own goal",body:"to harm yourself by your own action",source:"“Bragging about the test before failing it was a classic own goal.”"},"fg-i1228":{src:"fig:idioms:1228",route:"#/figurative",cta:"More idioms",title:"Idiom · settle the score",body:"to get even for a past wrong",source:"“The rematch let our chess club settle the score with the rival school.”"},"fg-i1229":{src:"fig:idioms:1229",route:"#/figurative",cta:"More idioms",title:"Idiom · show your hand",body:"to reveal your secret plans or intentions",source:"“Asking to borrow the big cake pan showed Mom's hand about the surprise party.”"},"fg-i1230":{src:"fig:idioms:1230",route:"#/figurative",cta:"More idioms",title:"Idiom · sidelined",body:"kept out of the action or ignored",source:"“A sprained wrist sidelined Jo from the handwriting contest.”"},"fg-i1231":{src:"fig:idioms:1231",route:"#/figurative",cta:"More idioms",title:"Idiom · slam dunk",body:"a guaranteed success; something certain",source:"“After three weeks of practice, her book report felt like a slam dunk.”"},"fg-i1232":{src:"fig:idioms:1232",route:"#/figurative",cta:"More idioms",title:"Idiom · step up to the plate",body:"to take responsibility and act when needed",source:"“When the club needed a treasurer, Priya stepped up to the plate.”"},"fg-i1233":{src:"fig:idioms:1233",route:"#/figurative",cta:"More idioms",title:"Idiom · sticky wicket",body:"a tricky, awkward situation",source:"“Two birthday parties on the same afternoon — what a sticky wicket.”"},"fg-i1234":{src:"fig:idioms:1234",route:"#/figurative",cta:"More idioms",title:"Idiom · take a shot in the dark",body:"to make a wild guess",source:"“Unsure of the state capital, he took a shot in the dark and said Helena.”"},"fg-i1235":{src:"fig:idioms:1235",route:"#/figurative",cta:"More idioms",title:"Idiom · take one for the team",body:"to accept something unpleasant to help your group",source:"“Ella took one for the team and played the boring narrator so the class play could go on.”"},"fg-i1236":{src:"fig:idioms:1236",route:"#/figurative",cta:"More idioms",title:"Idiom · the gloves are off",body:"polite behavior has ended; real conflict begins",source:"“After the tied quiz score, the gloves were off between the two teams.”"},"fg-i1237":{src:"fig:idioms:1237",route:"#/figurative",cta:"More idioms",title:"Idiom · throw a curveball",body:"to surprise someone with something unexpected",source:"“The judges threw a curveball by asking for each word's language of origin.”"},"fg-i1238":{src:"fig:idioms:1238",route:"#/figurative",cta:"More idioms",title:"Idiom · throw in your hand",body:"to give up on something",source:"“Halfway through the thousand-piece puzzle, Uncle Raj threw in his hand.”"},"fg-i1239":{src:"fig:idioms:1239",route:"#/figurative",cta:"More idioms",title:"Idiom · toe to toe",body:"facing an opponent directly as an equal",source:"“Maya went toe to toe with last year's champion in the final round.”"},"fg-i1240":{src:"fig:idioms:1240",route:"#/figurative",cta:"More idioms",title:"Idiom · touch base",body:"to make brief contact to share news",source:"“Ms. Rivera touches base with parents every Friday by email.”"},"fg-i1241":{src:"fig:idioms:1241",route:"#/figurative",cta:"More idioms",title:"Idiom · trump card",body:"a hidden advantage saved for the right moment",source:"“Her trump card at the bake sale was Grandma's secret brownie recipe.”"},"fg-i1242":{src:"fig:idioms:1242",route:"#/figurative",cta:"More idioms",title:"Idiom · up your game",body:"to improve your performance",source:"“New rivals joined the bee this year, so Zoe upped her game with daily drills.”"},"fg-i1243":{src:"fig:idioms:1243",route:"#/figurative",cta:"More idioms",title:"Idiom · victory lap",body:"a public celebration of a success",source:"“After acing the recital, Leo took a victory lap around the kitchen.”"},"fg-i1244":{src:"fig:idioms:1244",route:"#/figurative",cta:"More idioms",title:"Idiom · win by a landslide",body:"to win by a very large margin",source:"“The pizza-party option won the class vote by a landslide.”"},"fg-i1245":{src:"fig:idioms:1245",route:"#/figurative",cta:"More idioms",title:"Idiom · wipe the floor with",body:"to defeat someone totally and easily",source:"“Big sister wiped the floor with us at charades again.”"},"fg-i1246":{src:"fig:idioms:1246",route:"#/figurative",cta:"More idioms",title:"Idiom · a war of words",body:"a long angry argument, especially in public",source:"“The two debate teams kept up a war of words all week.”"},"fg-i1247":{src:"fig:idioms:1247",route:"#/figurative",cta:"More idioms",title:"Idiom · all quiet on the western front",body:"nothing new is happening; a calm period",source:"“'All quiet on the western front,' Dad whispered, peeking in at the napping twins.”"},"fg-i1248":{src:"fig:idioms:1248",route:"#/figurative",cta:"More idioms",title:"Idiom · armed to the hilt",body:"carrying every possible weapon or resource",source:"“Nina arrived at the bee armed to the hilt: flashcards, dictionary, and three sharpened pencils.”"},"fg-i1249":{src:"fig:idioms:1249",route:"#/figurative",cta:"More idioms",title:"Idiom · AWOL",body:"absent without permission",source:"“The stapler has gone AWOL from the teacher's desk again.”"},"fg-i1250":{src:"fig:idioms:1250",route:"#/figurative",cta:"More idioms",title:"Idiom · battle of wits",body:"a contest of cleverness between rivals",source:"“The chess final turned into a battle of wits between the twins.”"},"fg-i1251":{src:"fig:idioms:1251",route:"#/figurative",cta:"More idioms",title:"Idiom · beat a hasty retreat",body:"to leave quickly to avoid trouble",source:"“Smelling burnt cookies, the kids beat a hasty retreat from the kitchen.”"},"fg-i1252":{src:"fig:idioms:1252",route:"#/figurative",cta:"More idioms",title:"Idiom · bite the dust",body:"to fail, break, or be defeated",source:"“My old backpack finally bit the dust on the last day of school.”"},"fg-i1253":{src:"fig:idioms:1253",route:"#/figurative",cta:"More idioms",title:"Idiom · break ranks",body:"to stop supporting your own group publicly",source:"“Ben broke ranks with his buddies and voted for the museum trip.”"},"fg-i1254":{src:"fig:idioms:1254",route:"#/figurative",cta:"More idioms",title:"Idiom · bring out the big guns",body:"to use your strongest resources or people",source:"“For the final round, Coach brought out the big guns: last year's championship words.”"},"fg-i1255":{src:"fig:idioms:1255",route:"#/figurative",cta:"More idioms",title:"Idiom · call to arms",body:"an urgent appeal for people to act",source:"“The flooded book fair was a call to arms for the whole PTA.”"},"fg-i1256":{src:"fig:idioms:1256",route:"#/figurative",cta:"More idioms",title:"Idiom · caught in the crossfire",body:"harmed by a conflict between others",source:"“When the twins argued over the remote, the cat got caught in the crossfire.”"},"fg-i1257":{src:"fig:idioms:1257",route:"#/figurative",cta:"More idioms",title:"Idiom · close ranks",body:"to unite and protect your own group",source:"“When outsiders teased the new kid, our class closed ranks around him.”"},"fg-i1258":{src:"fig:idioms:1258",route:"#/figurative",cta:"More idioms",title:"Idiom · come out fighting",body:"to respond to trouble with energy and determination",source:"“After a low quiz score, Ana came out fighting with a color-coded study plan.”"},"fg-i1259":{src:"fig:idioms:1259",route:"#/figurative",cta:"More idioms",title:"Idiom · declare war on",body:"to announce a determined campaign against something",source:"“Mom has declared war on the sock pile under my bed.”"},"fg-i1260":{src:"fig:idioms:1260",route:"#/figurative",cta:"More idioms",title:"Idiom · dig in your heels",body:"to refuse stubbornly to change or move",source:"“Priya dug in her heels about keeping her lucky pencil for every test.”"},"fg-i1261":{src:"fig:idioms:1261",route:"#/figurative",cta:"More idioms",title:"Idiom · draw first blood",body:"to strike the first blow in a contest",source:"“Our team drew first blood with a perfect score in round one.”"},"fg-i1262":{src:"fig:idioms:1262",route:"#/figurative",cta:"More idioms",title:"Idiom · drop a bombshell",body:"to reveal shocking, unexpected news",source:"“Grandpa dropped a bombshell at dinner: we're moving to Seattle in June.”"},"fg-i1263":{src:"fig:idioms:1263",route:"#/figurative",cta:"More idioms",title:"Idiom · fall on your sword",body:"to accept all the blame and resign",source:"“After the group project flopped, the team captain fell on his sword and took the blame.”"},"fg-i1264":{src:"fig:idioms:1264",route:"#/figurative",cta:"More idioms",title:"Idiom · fight a losing battle",body:"to keep trying at something that cannot succeed",source:"“Keeping glitter off the floor during craft hour is fighting a losing battle.”"},"fg-i1265":{src:"fig:idioms:1265",route:"#/figurative",cta:"More idioms",title:"Idiom · fight tooth and nail",body:"to fight or resist with every ounce of effort",source:"“Ravi fought tooth and nail for the last spot on the mathlete team.”"},"fg-i1266":{src:"fig:idioms:1266",route:"#/figurative",cta:"More idioms",title:"Idiom · first line of defense",body:"the first protection against a problem",source:"“Washing your hands is the first line of defense against classroom colds.”"},"fg-i1267":{src:"fig:idioms:1267",route:"#/figurative",cta:"More idioms",title:"Idiom · friendly fire",body:"accidental harm caused by your own side",source:"“Dad's joke about my haircut was friendly fire — he'd meant to tease my brother.”"},"fg-i1268":{src:"fig:idioms:1268",route:"#/figurative",cta:"More idioms",title:"Idiom · front line workers",body:"people whose jobs face danger or the public directly",source:"“Our class made thank-you cards for the front line workers at the hospital.”"},"fg-i1269":{src:"fig:idioms:1269",route:"#/figurative",cta:"More idioms",title:"Idiom · gain ground",body:"to make progress or become more accepted",source:"“Her reading is gaining ground — up two levels in one year.”"},"fg-i1270":{src:"fig:idioms:1270",route:"#/figurative",cta:"More idioms",title:"Idiom · go down fighting",body:"to keep trying until the very end",source:"“Down to his last card in the tournament, Milo went down fighting.”"},"fg-i1271":{src:"fig:idioms:1271",route:"#/figurative",cta:"More idioms",title:"Idiom · go great guns",body:"to succeed quickly and energetically",source:"“The lemonade stand is going great guns — three pitchers sold before lunch.”"},"fg-i1272":{src:"fig:idioms:1272",route:"#/figurative",cta:"More idioms",title:"Idiom · gun for someone",body:"to be determined to beat or bring down someone",source:"“Every speller in the county is gunning for the returning champion.”"},"fg-i1273":{src:"fig:idioms:1273",route:"#/figurative",cta:"More idioms",title:"Idiom · half the battle",body:"a big part of finishing something difficult",source:"“Just opening the math book is half the battle.”"},"fg-i1274":{src:"fig:idioms:1274",route:"#/figurative",cta:"More idioms",title:"Idiom · hold the fort",body:"to keep things running while others are away",source:"“Mom held the fort at the bake-sale table while we hunted for extra napkins.”"},"fg-i1275":{src:"fig:idioms:1275",route:"#/figurative",cta:"More idioms",title:"Idiom · hold your fire",body:"to wait before attacking or criticizing",source:"“Hold your fire until your sister finishes explaining what happened to the cake.”"},"fg-i1276":{src:"fig:idioms:1276",route:"#/figurative",cta:"More idioms",title:"Idiom · in the firing line",body:"in a position to be blamed or attacked",source:"“As team captain, Rosa was in the firing line when the project ran late.”"},"fg-i1277":{src:"fig:idioms:1277",route:"#/figurative",cta:"More idioms",title:"Idiom · in the trenches",body:"doing the hard, unglamorous work firsthand",source:"“Ms. Lee has spent twenty years in the trenches of third-grade teaching.”"},"fg-i1278":{src:"fig:idioms:1278",route:"#/figurative",cta:"More idioms",title:"Idiom · lock and load",body:"to get fully ready for action",source:"“Backpacks zipped and lunches packed — lock and load for the field trip.”"},"fg-i1279":{src:"fig:idioms:1279",route:"#/figurative",cta:"More idioms",title:"Idiom · long march",body:"a long, exhausting effort toward a distant goal",source:"“Learning cursive felt like a long march, one loopy letter at a time.”"},"fg-i1280":{src:"fig:idioms:1280",route:"#/figurative",cta:"More idioms",title:"Idiom · lose ground",body:"to fall behind or lose an advantage",source:"“Skipping practice all week made Dev lose ground to the other spellers.”"},"fg-i1281":{src:"fig:idioms:1281",route:"#/figurative",cta:"More idioms",title:"Idiom · man the barricades",body:"to rise up and defend a cause",source:"“When the library budget was cut, parents manned the barricades at the town meeting.”"},"fg-i1282":{src:"fig:idioms:1282",route:"#/figurative",cta:"More idioms",title:"Idiom · mark time",body:"to wait without making real progress",source:"“We marked time with word searches until the assembly began.”"},"fg-i1283":{src:"fig:idioms:1283",route:"#/figurative",cta:"More idioms",title:"Idiom · meet your Waterloo",body:"to suffer a final, crushing defeat",source:"“The defending champion met her Waterloo on the word 'chiaroscuro.'”"},"fg-i1284":{src:"fig:idioms:1284",route:"#/figurative",cta:"More idioms",title:"Idiom · no man's land",body:"a dangerous or unclaimed in-between area",source:"“The hallway between the two rival classrooms became no man's land during the prank war.”"},"fg-i1285":{src:"fig:idioms:1285",route:"#/figurative",cta:"More idioms",title:"Idiom · on the warpath",body:"very angry and looking for a confrontation",source:"“Somebody tracked mud across the new carpet, and Mom is on the warpath.”"},"fg-i1286":{src:"fig:idioms:1286",route:"#/figurative",cta:"More idioms",title:"Idiom · open fire",body:"to begin attacking or criticizing",source:"“The moment the debate began, both sides opened fire with statistics.”"},"fg-i1287":{src:"fig:idioms:1287",route:"#/figurative",cta:"More idioms",title:"Idiom · parting shot",body:"a final sharp remark made while leaving",source:"“Her parting shot as she left the game: 'Practice spelling W-I-N.'”"},"fg-i1288":{src:"fig:idioms:1288",route:"#/figurative",cta:"More idioms",title:"Idiom · pick your battles",body:"to spend energy only on fights worth winning",source:"“Dad picks his battles: messy rooms slide, but homework never does.”"},"fg-i1289":{src:"fig:idioms:1289",route:"#/figurative",cta:"More idioms",title:"Idiom · pull rank",body:"to use your higher position to force obedience",source:"“The big kids pulled rank and claimed the good swings.”"},"fg-i1290":{src:"fig:idioms:1290",route:"#/figurative",cta:"More idioms",title:"Idiom · pull the trigger",body:"to finally make a decision and act",source:"“After weeks of debating, we pulled the trigger on adopting the shelter puppy.”"},"fg-i1291":{src:"fig:idioms:1291",route:"#/figurative",cta:"More idioms",title:"Idiom · rally the troops",body:"to gather and inspire your group to act",source:"“Before the relay, Coach rallied the troops with a silly cheer.”"},"fg-i1292":{src:"fig:idioms:1292",route:"#/figurative",cta:"More idioms",title:"Idiom · run the gauntlet",body:"to endure attacks or criticism from all sides",source:"“Every science fair idea must run the gauntlet of the judges' questions.”"},"fg-i1293":{src:"fig:idioms:1293",route:"#/figurative",cta:"More idioms",title:"Idiom · shell-shocked",body:"stunned and dazed by a shocking experience",source:"“We walked out of the surprise math test looking shell-shocked.”"},"fg-i1294":{src:"fig:idioms:1294",route:"#/figurative",cta:"More idioms",title:"Idiom · shot in the arm",body:"something that quickly restores energy or confidence",source:"“Winning the class quiz was a shot in the arm for Theo's confidence.”"},"fg-i1295":{src:"fig:idioms:1295",route:"#/figurative",cta:"More idioms",title:"Idiom · soldier on",body:"to keep going despite difficulty or discouragement",source:"“Her voice was scratchy, but Lena soldiered on through the whole recital.”"},"fg-i1296":{src:"fig:idioms:1296",route:"#/figurative",cta:"More idioms",title:"Idiom · stand your ground",body:"to refuse to retreat from your position or belief",source:"“Kim stood her ground about the answer, and the key proved her right.”"},"fg-i1297":{src:"fig:idioms:1297",route:"#/figurative",cta:"More idioms",title:"Idiom · stick to your guns",body:"to hold firm to your beliefs despite pressure",source:"“Everyone doubted his book-club pick, but Amir stuck to his guns.”"},"fg-i1298":{src:"fig:idioms:1298",route:"#/figurative",cta:"More idioms",title:"Idiom · take by storm",body:"to impress or conquer suddenly and completely",source:"“The kindergartners' kazoo band took the talent show by storm.”"},"fg-i1299":{src:"fig:idioms:1299",route:"#/figurative",cta:"More idioms",title:"Idiom · take cover",body:"to hide quickly from danger",source:"“The picnic ended with everyone taking cover from a sudden hailstorm.”"},"fg-i1300":{src:"fig:idioms:1300",route:"#/figurative",cta:"More idioms",title:"Idiom · take flak",body:"to receive strong criticism",source:"“Sam took flak from his cousins for rooting against their team.”"},"fg-i1301":{src:"fig:idioms:1301",route:"#/figurative",cta:"More idioms",title:"Idiom · take no prisoners",body:"to act with ruthless determination",source:"“Grandma takes no prisoners at the Scrabble board.”"},"fg-i1302":{src:"fig:idioms:1302",route:"#/figurative",cta:"More idioms",title:"Idiom · the big guns",body:"the most powerful or important people",source:"“For the spring concert, the school brought in the big guns: the high school orchestra.”"},"fg-i1303":{src:"fig:idioms:1303",route:"#/figurative",cta:"More idioms",title:"Idiom · tilt at windmills",body:"to fight imaginary enemies or hopeless causes",source:"“Arguing with the vending machine is tilting at windmills, Dad.”"},"fg-i1304":{src:"fig:idioms:1304",route:"#/figurative",cta:"More idioms",title:"Idiom · war chest",body:"money saved up for a big campaign or fight",source:"“The club's cookie-sale war chest will buy new dictionaries.”"},"fg-i1305":{src:"fig:idioms:1305",route:"#/figurative",cta:"More idioms",title:"Idiom · win the battle but lose the war",body:"to gain a small victory that costs the bigger goal",source:"“He won the battle over bedtime but lost the war when Mom canceled the sleepover.”"},"fg-i1306":{src:"fig:idioms:1306",route:"#/figurative",cta:"More idioms",title:"Idiom · young Turk",body:"an impatient young person pushing for change",source:"“The young Turks of the student council want recess moved before lunch.”"},"fg-i1307":{src:"fig:idioms:1307",route:"#/figurative",cta:"More idioms",title:"Idiom · zero hour",body:"the exact moment something important begins",source:"“Zero hour for the science-fair setup is 8 a.m. sharp.”"},"fg-i1308":{src:"fig:idioms:1308",route:"#/figurative",cta:"More idioms",title:"Idiom · flogging a dead horse",body:"wasting effort on something already settled or hopeless",source:"“Asking for a later bedtime again is flogging a dead horse.”"},"fg-i1309":{src:"fig:idioms:1309",route:"#/figurative",cta:"More idioms",title:"Idiom · fly in the ointment",body:"one small flaw that spoils something good",source:"“The picnic was perfect except one fly in the ointment: we forgot the lemonade.”"},"fg-i1310":{src:"fig:idioms:1310",route:"#/figurative",cta:"More idioms",title:"Idiom · fly off the handle",body:"to lose your temper suddenly",source:"“Dad tries not to fly off the handle when we spill juice in the car.”"},"fg-i1311":{src:"fig:idioms:1311",route:"#/figurative",cta:"More idioms",title:"Idiom · for the birds",body:"worthless or not worth taking seriously",source:"“Marco says homework on weekends is for the birds.”"},"fg-i1312":{src:"fig:idioms:1312",route:"#/figurative",cta:"More idioms",title:"Idiom · fortune favors the bold",body:"brave people are the most likely to succeed",source:"“Fortune favors the bold, so raise your hand even if you're not sure.”"},"fg-i1313":{src:"fig:idioms:1313",route:"#/figurative",cta:"More idioms",title:"Idiom · from rags to riches",body:"rising from poverty to wealth",source:"“The spelling champ went from rags to riches: last place one year, the trophy the next.”"},"fg-i1314":{src:"fig:idioms:1314",route:"#/figurative",cta:"More idioms",title:"Idiom · from scratch",body:"from the very beginning, using nothing ready-made",source:"“We baked the birthday cake from scratch, flour and all.”"},"fg-i1315":{src:"fig:idioms:1315",route:"#/figurative",cta:"More idioms",title:"Idiom · full steam ahead",body:"moving forward with all possible speed and energy",source:"“With the science fair one week away, it's full steam ahead on our volcano.”"},"fg-i1316":{src:"fig:idioms:1316",route:"#/figurative",cta:"More idioms",title:"Idiom · get a kick out of",body:"to really enjoy something",source:"“Grandma gets a kick out of hearing me spell 'onomatopoeia.'”"},"fg-i1317":{src:"fig:idioms:1317",route:"#/figurative",cta:"More idioms",title:"Idiom · get off scot-free",body:"to escape without any punishment or cost",source:"“The cat knocked over the vase and got off scot-free because we blamed the dog.”"},"fg-i1318":{src:"fig:idioms:1318",route:"#/figurative",cta:"More idioms",title:"Idiom · get the sack",body:"to be fired from a job",source:"“In our class store game, the napping shopkeeper got the sack.”"},"fg-i1319":{src:"fig:idioms:1319",route:"#/figurative",cta:"More idioms",title:"Idiom · get your ducks in a row",body:"to get everything organized before starting",source:"“Mom had us get our ducks in a row the night before the bee: pencils, water, word list.”"},"fg-i1320":{src:"fig:idioms:1320",route:"#/figurative",cta:"More idioms",title:"Idiom · give the benefit of the doubt",body:"to believe someone is innocent or honest when you are unsure",source:"“I couldn't find my eraser, but I gave my desk mate the benefit of the doubt.”"},"fg-i1321":{src:"fig:idioms:1321",route:"#/figurative",cta:"More idioms",title:"Idiom · go against the grain",body:"to be opposite to what feels natural or usual",source:"“It goes against the grain for Priya to leave a puzzle unfinished.”"},"fg-i1322":{src:"fig:idioms:1322",route:"#/figurative",cta:"More idioms",title:"Idiom · go down in flames",body:"to fail suddenly and spectacularly",source:"“Our plan to surprise Mom went down in flames when the balloons popped early.”"},"fg-i1323":{src:"fig:idioms:1323",route:"#/figurative",cta:"More idioms",title:"Idiom · go for broke",body:"to risk everything on one big effort",source:"“Down to the final round, she went for broke and asked for the hardest word.”"},"fg-i1324":{src:"fig:idioms:1324",route:"#/figurative",cta:"More idioms",title:"Idiom · go pear-shaped",body:"to go badly wrong",source:"“The bake sale went pear-shaped when the oven quit an hour before school.”"},"fg-i1325":{src:"fig:idioms:1325",route:"#/figurative",cta:"More idioms",title:"Idiom · go to the dogs",body:"to fall into a much worse condition",source:"“Grandpa jokes the playground has gone to the dogs since they removed the tire swing.”"},"fg-i1326":{src:"fig:idioms:1326",route:"#/figurative",cta:"More idioms",title:"Idiom · golden handshake",body:"a large payment given to someone leaving a job",source:"“The retiring principal got a golden handshake and a very long round of applause.”"},"fg-i1327":{src:"fig:idioms:1327",route:"#/figurative",cta:"More idioms",title:"Idiom · gravy train",body:"an easy job or situation that pays very well",source:"“Being line leader is no gravy train; you have to hold every single door.”"},"fg-i1328":{src:"fig:idioms:1328",route:"#/figurative",cta:"More idioms",title:"Idiom · grease the wheels",body:"to make things run smoothly, often with favors or money",source:"“A thank-you note to the librarian greased the wheels for our book-club room.”"},"fg-i1329":{src:"fig:idioms:1329",route:"#/figurative",cta:"More idioms",title:"Idiom · hair of the dog",body:"a little more of what hurt you, taken as a cure",source:"“Sore from practice, Dad joked that a light jog was the hair of the dog.”"},"fg-i1330":{src:"fig:idioms:1330",route:"#/figurative",cta:"More idioms",title:"Idiom · hand over fist",body:"quickly and in large amounts, especially money",source:"“The lemonade stand made money hand over fist during the heat wave.”"},"fg-i1331":{src:"fig:idioms:1331",route:"#/figurative",cta:"More idioms",title:"Idiom · hang by a thread",body:"to be in a very fragile, risky situation",source:"“Our team's win hung by a thread until the other finalist missed.”"},"fg-i1332":{src:"fig:idioms:1332",route:"#/figurative",cta:"More idioms",title:"Idiom · hang in the balance",body:"to be undecided, with success or failure equally possible",source:"“The class party hangs in the balance until our reading-minutes chart is tallied.”"},"fg-i1333":{src:"fig:idioms:1333",route:"#/figurative",cta:"More idioms",title:"Idiom · hard nut to crack",body:"a problem or person that is difficult to figure out",source:"“The bonus word was a hard nut to crack, even for the champ.”"},"fg-i1334":{src:"fig:idioms:1334",route:"#/figurative",cta:"More idioms",title:"Idiom · haste makes waste",body:"rushing causes mistakes that cost more time",source:"“I glued the wrong flap first — haste makes waste.”"},"fg-i1335":{src:"fig:idioms:1335",route:"#/figurative",cta:"More idioms",title:"Idiom · have a bone to pick",body:"to have a complaint to argue out with someone",source:"“Mia has a bone to pick with her brother about the missing markers.”"},"fg-i1336":{src:"fig:idioms:1336",route:"#/figurative",cta:"More idioms",title:"Idiom · have bigger fish to fry",body:"to have more important things to deal with",source:"“Coach ignored our jersey debate; she had bigger fish to fry before the tournament.”"},"fg-i1337":{src:"fig:idioms:1337",route:"#/figurative",cta:"More idioms",title:"Idiom · head in the clouds",body:"daydreaming instead of paying attention",source:"“Leo missed his turn to spell because his head was in the clouds.”"},"fg-i1338":{src:"fig:idioms:1338",route:"#/figurative",cta:"More idioms",title:"Idiom · head over heels",body:"completely, especially completely in love",source:"“Grandpa is still head over heels for Grandma after fifty years.”"},"fg-i1339":{src:"fig:idioms:1339",route:"#/figurative",cta:"More idioms",title:"Idiom · heart of gold",body:"a truly kind and generous nature",source:"“The crossing guard who remembers every kid's name has a heart of gold.”"},"fg-i1340":{src:"fig:idioms:1340",route:"#/figurative",cta:"More idioms",title:"Idiom · heart of stone",body:"a cold nature with no pity",source:"“You'd need a heart of stone to say no to the puppy's eyes at dinner.”"},"fg-i1341":{src:"fig:idioms:1341",route:"#/figurative",cta:"More idioms",title:"Idiom · hedge your bets",body:"to protect yourself by backing more than one option",source:"“Sam hedged his bets by studying both word lists in case the bee used either.”"},"fg-i1342":{src:"fig:idioms:1342",route:"#/figurative",cta:"More idioms",title:"Idiom · hit rock bottom",body:"to reach the lowest possible point",source:"“My motivation hit rock bottom until Mom turned flash cards into a game.”"},"fg-i1343":{src:"fig:idioms:1343",route:"#/figurative",cta:"More idioms",title:"Idiom · hit the road",body:"to leave or begin a journey",source:"“Pack the snacks — we hit the road for Grandma's at seven.”"},"fg-i1344":{src:"fig:idioms:1344",route:"#/figurative",cta:"More idioms",title:"Idiom · hit the sack",body:"to go to bed",source:"“Big test tomorrow, so I'm hitting the sack early.”"},"fg-i1345":{src:"fig:idioms:1345",route:"#/figurative",cta:"More idioms",title:"Idiom · hook, line and sinker",body:"believing something completely, without any doubt",source:"“Dad fell for our fake birthday plans hook, line and sinker.”"},"fg-i1346":{src:"fig:idioms:1346",route:"#/figurative",cta:"More idioms",title:"Idiom · in the driver's seat",body:"in control of what happens",source:"“With the highest score, Ava is in the driver's seat going into the final round.”"},"fg-i1347":{src:"fig:idioms:1347",route:"#/figurative",cta:"More idioms",title:"Idiom · in the pipeline",body:"already being worked on and coming soon",source:"“The librarian says more graphic novels are in the pipeline for spring.”"},"fg-i1348":{src:"fig:idioms:1348",route:"#/figurative",cta:"More idioms",title:"Idiom · in the red",body:"losing money or in debt",source:"“Our bake-sale budget was in the red until Saturday's cookie rush.”"},"fg-i1349":{src:"fig:idioms:1349",route:"#/figurative",cta:"More idioms",title:"Idiom · jump ship",body:"to abandon a group or job, often for another",source:"“Half the chess club jumped ship when the robotics team got new kits.”"},"fg-i1350":{src:"fig:idioms:1350",route:"#/figurative",cta:"More idioms",title:"Idiom · jump the gun",body:"to start before the proper time",source:"“Don't jump the gun — wait until the judge finishes saying the word.”"},"fg-i1351":{src:"fig:idioms:1351",route:"#/figurative",cta:"More idioms",title:"Idiom · keep a stiff upper lip",body:"to stay brave and hide your feelings in hard times",source:"“Ben kept a stiff upper lip after misspelling, then practiced twice as hard.”"},"fg-i1352":{src:"fig:idioms:1352",route:"#/figurative",cta:"More idioms",title:"Idiom · keep at arm's length",body:"to avoid becoming close or friendly with someone",source:"“Mom keeps the class hamster at arm's length because of her allergies.”"},"fg-i1353":{src:"fig:idioms:1353",route:"#/figurative",cta:"More idioms",title:"Idiom · keep the wolf from the door",body:"to earn just enough to avoid hunger or poverty",source:"“Grandpa says his first paper route barely kept the wolf from the door.”"},"fg-i1354":{src:"fig:idioms:1354",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your ear to the ground",body:"to stay alert for early news or changes",source:"“Keep your ear to the ground for the soccer tryout dates.”"},"fg-i1355":{src:"fig:idioms:1355",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your nose clean",body:"to stay out of trouble",source:"“The coach's only rule over break: keep your nose clean and stretch daily.”"},"fg-i1356":{src:"fig:idioms:1356",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your powder dry",body:"to stay calm and save your resources until truly needed",source:"“Don't argue every little call, Dad says — keep your powder dry for what matters.”"},"fg-i1357":{src:"fig:idioms:1357",route:"#/figurative",cta:"More idioms",title:"Idiom · lay it on thick",body:"to exaggerate praise, flattery, or drama",source:"“Jaya laid it on thick about Mom's haircut right before asking for a sleepover.”"},"fg-i1358":{src:"fig:idioms:1358",route:"#/figurative",cta:"More idioms",title:"Idiom · level playing field",body:"fair conditions where no one starts with an advantage",source:"“Giving younger spellers easier words keeps a level playing field.”"},"fg-i1359":{src:"fig:idioms:1359",route:"#/figurative",cta:"More idioms",title:"Idiom · like a broken record",body:"repeating the same thing over and over",source:"“I sound like a broken record: shoes off at the door!”"},"fg-i1360":{src:"fig:idioms:1360",route:"#/figurative",cta:"More idioms",title:"Idiom · lip service",body:"support given in words but not in actions",source:"“Paying lip service to tidying up won't actually clean the toy shelf.”"},"fg-i1361":{src:"fig:idioms:1361",route:"#/figurative",cta:"More idioms",title:"Idiom · live on a shoestring",body:"to live or operate on very little money",source:"“The drama club lives on a shoestring, so we paint our own sets.”"},"fg-i1362":{src:"fig:idioms:1362",route:"#/figurative",cta:"More idioms",title:"Idiom · lock, stock and barrel",body:"absolutely everything, the whole of something",source:"“We moved Grandma's sewing room lock, stock and barrel to the new house.”"},"fg-i1363":{src:"fig:idioms:1363",route:"#/figurative",cta:"More idioms",title:"Idiom · long in the tooth",body:"getting old",source:"“Our minivan is long in the tooth, but it still makes the school run.”"},"fg-i1364":{src:"fig:idioms:1364",route:"#/figurative",cta:"More idioms",title:"Idiom · low-hanging fruit",body:"the easiest tasks or targets to start with",source:"“Start your review with the low-hanging fruit: the words you almost know.”"},"fg-i1365":{src:"fig:idioms:1365",route:"#/figurative",cta:"More idioms",title:"Idiom · make waves",body:"to cause a stir or challenge how things are done",source:"“The new student made waves by suggesting homework-free Fridays.”"},"fg-i1366":{src:"fig:idioms:1366",route:"#/figurative",cta:"More idioms",title:"Idiom · method to the madness",body:"a hidden plan behind seemingly crazy behavior",source:"“Dad's messy desk has a method to the madness; he finds any paper in seconds.”"},"fg-i1367":{src:"fig:idioms:1367",route:"#/figurative",cta:"More idioms",title:"Idiom · more than meets the eye",body:"more interesting or complicated than it first appears",source:"“There's more than meets the eye to the quiet kid who won the chess trophy.”"},"fg-i1368":{src:"fig:idioms:1368",route:"#/figurative",cta:"More idioms",title:"Idiom · move the goalposts",body:"to change the rules or target unfairly partway through",source:"“First it was ten books, now it's fifteen — stop moving the goalposts!”"},"fg-i1369":{src:"fig:idioms:1369",route:"#/figurative",cta:"More idioms",title:"Idiom · music to my ears",body:"news that is delightful to hear",source:"“'Snow day' was music to my ears.”"},"fg-i1370":{src:"fig:idioms:1370",route:"#/figurative",cta:"More idioms",title:"Idiom · nail-biter",body:"a contest or story so tense you can hardly watch",source:"“The bee came down to two spellers — a real nail-biter.”"},"fg-i1371":{src:"fig:idioms:1371",route:"#/figurative",cta:"More idioms",title:"Idiom · neck and neck",body:"exactly even in a close race",source:"“Maya and Josh were neck and neck until the final word.”"},"fg-i1372":{src:"fig:idioms:1372",route:"#/figurative",cta:"More idioms",title:"Idiom · nest egg",body:"money saved up for the future",source:"“My allowance nest egg is finally big enough for the telescope.”"},"fg-i1373":{src:"fig:idioms:1373",route:"#/figurative",cta:"More idioms",title:"Idiom · new lease on life",body:"a fresh chance to enjoy living, with renewed energy",source:"“New glasses gave Grandpa a new lease on life at his woodworking bench.”"},"fg-i1374":{src:"fig:idioms:1374",route:"#/figurative",cta:"More idioms",title:"Idiom · not the sharpest tool in the shed",body:"not very smart",source:"“Our goldfish, bless him, is not the sharpest tool in the shed.”"},"fg-i1375":{src:"fig:idioms:1375",route:"#/figurative",cta:"More idioms",title:"Idiom · off the cuff",body:"spoken without preparation",source:"“Asked about her win, Zoe gave a sweet off-the-cuff thank-you speech.”"},"fg-i1376":{src:"fig:idioms:1376",route:"#/figurative",cta:"More idioms",title:"Idiom · off the hook",body:"freed from blame or an unwanted duty",source:"“Rain canceled practice, so I'm off the hook for cleaning the equipment.”"},"fg-i1377":{src:"fig:idioms:1377",route:"#/figurative",cta:"More idioms",title:"Idiom · old flame",body:"a person you loved in the past",source:"“At the reunion, Grandma laughed with an old flame from her school dances.”"},"fg-i1378":{src:"fig:idioms:1378",route:"#/figurative",cta:"More idioms",title:"Idiom · on a wing and a prayer",body:"barely managing, relying on luck and hope",source:"“We finished the poster on a wing and a prayer, gluing as the bell rang.”"},"fg-i1379":{src:"fig:idioms:1379",route:"#/figurative",cta:"More idioms",title:"Idiom · on the back burner",body:"set aside to deal with later",source:"“The treehouse plan is on the back burner until report cards come out.”"},"fg-i1380":{src:"fig:idioms:1380",route:"#/figurative",cta:"More idioms",title:"Idiom · open a can of worms",body:"to start something that creates many new problems",source:"“Asking who broke the stapler opened a can of worms in class.”"},"fg-i1381":{src:"fig:idioms:1381",route:"#/figurative",cta:"More idioms",title:"Idiom · paddle your own canoe",body:"to be independent and manage your own affairs",source:"“Grandpa's graduation advice was simple: paddle your own canoe.”"},"fg-i1382":{src:"fig:idioms:1382",route:"#/figurative",cta:"More idioms",title:"Idiom · par for the course",body:"just what you would expect, often mildly disappointing",source:"“Losing one mitten by January is par for the course in our family.”"},"fg-i1383":{src:"fig:idioms:1383",route:"#/figurative",cta:"More idioms",title:"Idiom · penny wise, pound foolish",body:"careful with small amounts of money but wasteful with big ones",source:"“Skipping the two-dollar bike lock and losing the bike was penny wise, pound foolish.”"},"fg-i1384":{src:"fig:idioms:1384",route:"#/figurative",cta:"More idioms",title:"Idiom · pie in the sky",body:"a lovely promise that will never really happen",source:"“A pool in our backyard is pie in the sky, but we keep asking.”"},"fg-i1385":{src:"fig:idioms:1385",route:"#/figurative",cta:"More idioms",title:"Idiom · play devil's advocate",body:"to argue the opposite side just to test an idea",source:"“Dad played devil's advocate at dinner, defending broccoli against us all.”"},"fg-i1386":{src:"fig:idioms:1386",route:"#/figurative",cta:"More idioms",title:"Idiom · pull the plug",body:"to stop something for good by cutting off its support",source:"“The principal pulled the plug on the fog machine after one hazy assembly.”"},"fg-i1387":{src:"fig:idioms:1387",route:"#/figurative",cta:"More idioms",title:"Idiom · put your foot in your mouth",body:"to say something embarrassing or tactless by accident",source:"“I put my foot in my mouth asking about the party I wasn't supposed to know about.”"},"fg-i1388":{src:"fig:idioms:1388",route:"#/figurative",cta:"More idioms",title:"Idiom · ride shotgun",body:"to sit in the front passenger seat",source:"“I called riding shotgun before my sister even had her shoes on.”"},"fg-i1389":{src:"fig:idioms:1389",route:"#/figurative",cta:"More idioms",title:"Idiom · right as rain",body:"perfectly fine or healthy",source:"“After a nap and some soup, Theo was right as rain for the recital.”"},"fg-i1390":{src:"fig:idioms:1390",route:"#/figurative",cta:"More idioms",title:"Idiom · roll with the punches",body:"to adapt calmly when things go wrong",source:"“Our picnic moved indoors twice, but we rolled with the punches.”"},"fg-i1391":{src:"fig:idioms:1391",route:"#/figurative",cta:"More idioms",title:"Idiom · rub elbows",body:"to mix socially with people, especially important ones",source:"“At the state bee, we rubbed elbows with last year's champion.”"},"fg-i1392":{src:"fig:idioms:1392",route:"#/figurative",cta:"More idioms",title:"Idiom · rub someone the wrong way",body:"to annoy someone without meaning to",source:"“The new kid's bragging rubbed the whole team the wrong way.”"},"fg-i1393":{src:"fig:idioms:1393",route:"#/figurative",cta:"More idioms",title:"Idiom · separate the wheat from the chaff",body:"to sort the valuable from the worthless",source:"“Tryouts separate the wheat from the chaff before the mathletes pick a team.”"},"fg-i1394":{src:"fig:idioms:1394",route:"#/figurative",cta:"More idioms",title:"Idiom · set in stone",body:"fixed and impossible to change",source:"“The seating chart isn't set in stone; Ms. Rivera shuffles it monthly.”"},"fg-i1395":{src:"fig:idioms:1395",route:"#/figurative",cta:"More idioms",title:"Idiom · shape up or ship out",body:"improve your behavior or leave",source:"“After the third missed practice, the coach's message was shape up or ship out.”"},"fg-i1396":{src:"fig:idioms:1396",route:"#/figurative",cta:"More idioms",title:"Idiom · ships that pass in the night",body:"people who meet briefly and then go their separate ways",source:"“My camp bunkmate and I were ships that pass in the night — one week, then different schools.”"},"fg-i1397":{src:"fig:idioms:1397",route:"#/figurative",cta:"More idioms",title:"Idiom · shoot the breeze",body:"to chat casually about nothing important",source:"“Dad and the neighbor shot the breeze over the fence while we drew chalk cities.”"},"fg-i1398":{src:"fig:idioms:1398",route:"#/figurative",cta:"More idioms",title:"Idiom · shot in the dark",body:"a guess made with almost no information",source:"“I hadn't studied that word, so my spelling was a shot in the dark.”"},"fg-i1399":{src:"fig:idioms:1399",route:"#/figurative",cta:"More idioms",title:"Idiom · silver bullet",body:"one simple solution that fixes everything instantly",source:"“Flash cards help, but there's no silver bullet for learning five hundred words.”"},"fg-i1400":{src:"fig:idioms:1400",route:"#/figurative",cta:"More idioms",title:"Idiom · silver spoon",body:"born into wealth and comfort",source:"“The book's hero had no silver spoon — she built her robot from junkyard parts.”"},"fg-i1401":{src:"fig:idioms:1401",route:"#/figurative",cta:"More idioms",title:"Idiom · sit on the fence",body:"to avoid choosing a side",source:"“Quit sitting on the fence — pizza party or movie day?”"},"fg-i1402":{src:"fig:idioms:1402",route:"#/figurative",cta:"More idioms",title:"Idiom · sitting duck",body:"an easy, defenseless target",source:"“Without an umbrella, I was a sitting duck for the sprinklers.”"},"fg-i1403":{src:"fig:idioms:1403",route:"#/figurative",cta:"More idioms",title:"Idiom · skate on thin ice",body:"to take a foolish risk",source:"“Turning in homework late twice in one week is skating on thin ice.”"},"fg-i1404":{src:"fig:idioms:1404",route:"#/figurative",cta:"More idioms",title:"Idiom · sleep on it",body:"to wait until the next day before deciding",source:"“Mom didn't say no to the sleepover; she said she'd sleep on it.”"},"fg-i1405":{src:"fig:idioms:1405",route:"#/figurative",cta:"More idioms",title:"Idiom · smoke and mirrors",body:"clever tricks that hide the truth",source:"“The 'mystery prize' was smoke and mirrors — just extra recess, which honestly we loved.”"},"fg-i1406":{src:"fig:idioms:1406",route:"#/figurative",cta:"More idioms",title:"Idiom · snake in the grass",body:"a hidden enemy pretending to be a friend",source:"“In the board game, my sweet little cousin turned out to be the snake in the grass.”"},"fg-i1407":{src:"fig:idioms:1407",route:"#/figurative",cta:"More idioms",title:"Idiom · spick and span",body:"completely clean and tidy",source:"“Our room has to be spick and span before screen time.”"},"fg-i1408":{src:"fig:idioms:1408",route:"#/figurative",cta:"More idioms",title:"Idiom · stab in the back",body:"a betrayal by someone you trusted",source:"“Sharing my secret hideout spot with the whole class felt like a stab in the back.”"},"fg-i1409":{src:"fig:idioms:1409",route:"#/figurative",cta:"More idioms",title:"Idiom · still waters run deep",body:"quiet people often have deep thoughts and strong feelings",source:"“Rosa barely talks in class, but her poems prove still waters run deep.”"},"fg-i1410":{src:"fig:idioms:1410",route:"#/figurative",cta:"More idioms",title:"Idiom · straight from the horse's mouth",body:"directly from the most reliable source",source:"“The field trip is Friday — straight from the horse's mouth, our principal.”"},"fg-i1411":{src:"fig:idioms:1411",route:"#/figurative",cta:"More idioms",title:"Idiom · strike while the iron is hot",body:"act quickly while the chance is there",source:"“Dad was in a great mood, so I struck while the iron was hot and asked about the puppy.”"},"fg-i1412":{src:"fig:idioms:1412",route:"#/figurative",cta:"More idioms",title:"Idiom · swan song",body:"a final performance or last piece of work",source:"“The retiring music teacher's spring concert was her swan song.”"},"fg-i1413":{src:"fig:idioms:1413",route:"#/figurative",cta:"More idioms",title:"Idiom · take the cake",body:"to be the most surprising or extreme of all",source:"“Of all your excuses, blaming the goldfish takes the cake.”"},"fg-i1414":{src:"fig:idioms:1414",route:"#/figurative",cta:"More idioms",title:"Idiom · take the plunge",body:"to finally commit to something big and scary",source:"“Nina took the plunge and signed up for the district bee.”"},"fg-i1415":{src:"fig:idioms:1415",route:"#/figurative",cta:"More idioms",title:"Idiom · take umbrage",body:"to feel offended",source:"“The cat took umbrage when we laughed at her tumble, and stalked off.”"},"fg-i1416":{src:"fig:idioms:1416",route:"#/figurative",cta:"More idioms",title:"Idiom · the apple doesn't fall far from the tree",body:"children usually turn out like their parents",source:"“She fixes computers just like her mom — the apple doesn't fall far from the tree.”"},"fg-i1417":{src:"fig:idioms:1417",route:"#/figurative",cta:"More idioms",title:"Idiom · the bigger they are, the harder they fall",body:"the powerful fail more dramatically than the small",source:"“Facing the returning champ, Coach whispered, 'The bigger they are, the harder they fall.'”"},"fg-i1418":{src:"fig:idioms:1418",route:"#/figurative",cta:"More idioms",title:"Idiom · the early bird gets the worm",body:"whoever acts first gets the reward",source:"“I claim the comfy beanbag at library time — the early bird gets the worm.”"},"fg-i1419":{src:"fig:idioms:1419",route:"#/figurative",cta:"More idioms",title:"Idiom · the proof is in the pudding",body:"you can only judge something by trying it",source:"“The study plan looks great, but the proof is in the pudding: Friday's quiz.”"},"fg-i1420":{src:"fig:idioms:1420",route:"#/figurative",cta:"More idioms",title:"Idiom · the straw that broke the camel's back",body:"the last small problem that finally causes collapse",source:"“The spilled glitter was the straw that broke the camel's back; craft time ended early.”"},"fg-i1421":{src:"fig:idioms:1421",route:"#/figurative",cta:"More idioms",title:"Idiom · there's no such thing as a free lunch",body:"everything costs something, even gifts",source:"“The 'free' game needed twenty dollars of gems — no such thing as a free lunch.”"},"fg-i1422":{src:"fig:idioms:1422",route:"#/figurative",cta:"More idioms",title:"Idiom · thick as thieves",body:"extremely close friends who share every secret",source:"“My cousin and I are thick as thieves every summer at the lake.”"},"fg-i1423":{src:"fig:idioms:1423",route:"#/figurative",cta:"More idioms",title:"Idiom · third wheel",body:"an extra person who isn't really needed",source:"“When my sister brings her best friend, I ride along as the third wheel.”"},"fg-i1424":{src:"fig:idioms:1424",route:"#/figurative",cta:"More idioms",title:"Idiom · throw caution to the wind",body:"to stop worrying and take a bold risk",source:"“On the last word, he threw caution to the wind and spelled it fast.”"},"fg-i1425":{src:"fig:idioms:1425",route:"#/figurative",cta:"More idioms",title:"Idiom · throw the baby out with the bathwater",body:"to discard something valuable while getting rid of the bad",source:"“Don't quit piano over one hard song — that's throwing the baby out with the bathwater.”"}});
